		iTime2 = temp;
	}

	iTime1 = iTime1 > 235959 ? 235959 : iTime1;
	iTime2 = iTime2 > 235959 ? 235959 : iTime2;

	int iHour1 = iTime1 / 10000;
	int iMin1 = (iTime1 % 10000) / 100;
	int iSec1 = iTime1 % 10000 % 100;
	int iHour2 = iTime2 / 10000;
	int iMin2 = (iTime2 % 10000) / 100;
	int iSec2 = iTime2 % 10000 % 100;

	int iSec = ((iHour2 - iHour1) * 3600 + (iMin2 - iMin1) * 60 + (iSec2 - iSec1));

//    LogFlow("���������iSec=" << iSec);
