			//
			 d_rate = i_diff_day/SCHEME_Base_TradeDate;
		}else if(i_diff_day == 0)
		{
			if(iNowTime>=93000 && iNowTime<=110000)
			{
				i_diff_sec =difftime_tosec(iNowTime,110000);
				d_diff_min =i_diff_sec/60.00;//���ٷ���
				d_rate = (d_diff_min + 120.00)/(4*60*SCHEME_Base_TradeDate);
			}else if(iNowTime>=13300 && iNowTime<=150000)
			{
				i_diff_sec =difftime_tosec(iNowTime,150000);
				d_diff_min =i_diff_sec/60.00;//���ٷ���
				d_rate = (d_diff_min)/(4*60*SCHEME_Base_TradeDate);
